parameters.jsCode:
const incomingKeyword = ($node['Telegram Trigger'].json.message.text || '').trim().toLowerCase();
const rows = $input.all().map(item => item.json);
const match = rows.find(row => String(row.keyword || row.trigger || '').trim().toLowerCase() === incomingKeyword);

if (!match) {
  return [{ json: { keyword: incomingKeyword, matched: false, consent_text: 'Могу задать несколько коротких вопросов, чтобы точнее понять вашу ситуацию?', first_question: 'Что сейчас больше всего мешает вам с памятью, интеллектом или системой обучения?', pattern_type: incomingKeyword } }];
}

return [{
  json: {
    ...match,
    keyword: incomingKeyword,
    matched: true,
    consent_text: match.consent_text || 'Могу задать несколько коротких вопросов, чтобы точнее понять вашу ситуацию?',
    first_question: match.first_open_question || match.first_question || 'Что именно вы хотите улучшить в первую очередь?',
    pattern_type: match.pattern_type || incomingKeyword
  }
}];

