parameters.jsCode:
const raw = $json.text || $json.output || $json.response || $json.content || JSON.stringify($json);
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim()) : raw;
} catch (error) {
  parsed = {
    next_sub_stage: $node['Postgres - UPSERT & Get State'].json.sub_stage || 'why_1_opportunities',
    message_text: 'Спасибо, понял. Расскажите чуть подробнее: что именно сейчас не получается и почему это важно решить?',
    is_target_icp: false,
    qualification_signals: { parse_error: error.message, raw_output: raw },
    lead_summary: '',
    offer_payload: {}
  };
}

return [{
  json: {
    next_sub_stage: parsed.next_sub_stage || 'why_1_opportunities',
    message_text: parsed.message_text || parsed.next_message || 'Спасибо, понял. Что для вас будет хорошим результатом?',
    is_target_icp: Boolean(parsed.is_target_icp),
    qualification_signals: parsed.qualification_signals || {},
    lead_summary: parsed.lead_summary || '',
    offer_payload: parsed.offer_payload || {}
  }
}];

