  qualification_signals = COALESCE(qualification_signals, '{}'::jsonb) || '${JSON.stringify($node["Code - Parse Gemini JSON"].json.qualification_signals || {}).replace(/'/g, "''")}'::jsonb,
  current_q_number = COALESCE(current_q_number, 0) + 1,
  updated_at = NOW()
WHERE telegram_user_id = ${$node["Telegram Trigger"].json.message.from.id}
RETURNING *;
` }}

